import { createProcessManager } from '@tuix/process-manager'

const pm = await createProcessManager()
await pm.add({
  name: 'shell',
  command: 'bash',
  pty: true,
  ptyCols: 80,
  ptyRows: 24,
})
await pm.start('shell')

import { createTestHarness } from '@tuix/testing'
import { test, expect } from 'bun:test'

test('counter', async () => {
  const harness = createTestHarness()
  await harness.run(Counter)
  await harness.send({ _tag: 'Increment' })
  const model = await harness.getState()
  expect(model.count).toBe(1)
  await harness.stop()
})

import { runApp } from '@tuix/jsx'
import { TuixApp } from '@tuix/bin'

// Install: bun add -g @tuix/bin
// Then run: tuix | tuix version | tuix help | tuix dashboard
runApp(TuixApp)

import { CoordinationModule } from '@tuix/coordination'
import type { EventBus } from '@tuix/core/events'

export function makeCoordination(eventBus: EventBus) {
  return new CoordinationModule(eventBus)
}

import { extractAppDoc, generateAppMarkdown, HelpExplorer } from '@tuix/docs'
import { Effect } from 'effect'

const docs = extractAppDoc(MyApp, 'myapp', '1.0.0')
const md = Effect.runSync(generateAppMarkdown(docs))
// Or render: <HelpExplorer docs={docs} />

import { Telemetry, createHttpTransport } from '@tuix/telemetry'

const transport = createHttpTransport({
  endpoint: 'https://metrics.example.com',
})

export function App() {
  return (
    <Telemetry enabled={false} appName="my-app" transport={transport}>
      <Main />
    </Telemetry>
  )
}

import { Updater } from '@tuix/update'

export function App() {
  return (
    <Updater
      packageName="@tuix/core"
      currentVersion="1.0.0"
      autoCheck={true}
      showBanner={true}
    >
      <Main />
    </Updater>
  )
}

